//
// Compare 2 file data type archives (.gdt). Output where data types exist only in one archive.
// Also indicate where the same named data type has a different type. This doesn't indicate
// where the internal contents of the same named data types differ.
//
//@category Data Types





using ghidra.app.script;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.program.model.dtarchive;
using ghidra.program.model.dtarchive;
using ghidra.util;

public class CompareGDTs : GhidraScript {

	private File firstFile;
	private File secondFile;
	private File outputFile;
	private FileDataTypeArchive archive1;
	private FileDataTypeArchive archive2;
	private DataTypeManager dtm1;
	private DataTypeManager dtm2;
	private PrintWriter printWriter;
	bool matchByName;
	bool checkPointers;
	bool checkArrays;

	/* @Override */
	protected void run()
    {
		firstFile = askFile("Select First GDT File", "Select 1st");
		secondFile = askFile("Select Second GDT File", "Select 2nd");
		outputFile = askFile("Select Output File", "Select output file");
		if (outputFile.exists()) {
			bool overwrite = askYesNo("Overwrite existing output file?",
				"The specified output file already exists. \nDo you want to overwrite it?");
			if (!overwrite) {
				println("Output file " + outputFile.getAbsolutePath() +
					" already exists. User aborted...");
				return;
			}
		}

		archive1 = openFileDataTypeArchive(firstFile, false);
		if (archive1.getWarning() != ArchiveWarning.NONE) {
			popup(
				"An architecture language error occured while opening archive (see log for details)\n" +
					firstFile.getPath());
			return;
		}

		archive2 = openFileDataTypeArchive(secondFile, false);
		if (archive2.getWarning() != ArchiveWarning.NONE) {
			popup(
				"An architecture language error occured while opening archive (see log for details)\n" +
					secondFile.getPath());
			archive1.release(this);
			return;
		}
		dtm1 = archive1.getDataTypeManager();
		dtm2 = archive2.getDataTypeManager();
		matchByName = askYesNo("Match Data Types By Path Name?",
			"Do you want to match data types by their path names (rather than by Universal ID)?");
		checkPointers = askYesNo("Check Pointers?", "Do you want to check Pointers?");
		checkArrays = askYesNo("Check Arrays?", "Do you want to check Arrays?");

		printWriter = new PrintWriter(outputFile);
		try {
			compareDataTypes();
		}
		finally {
			printWriter.close();
			archive1.release(this);
			archive2.release(this);
		}
	}

	private void output(string message) {
		printWriter.println(message);
	}

	private void compareDataTypes() {

		output("\nComparing " + firstFile.getAbsolutePath() + "\n        & " +
			secondFile.getAbsolutePath() + ".");

		output("\nThe following data types are only in " + firstFile.getAbsolutePath() + ".");
		long onlyInFirst = outputEachDataTypeOnlyInFirst(dtm1, dtm2);
		output(onlyInFirst + " data types that were only in first archive.");

		output("\nThe following data types are only in " + secondFile.getAbsolutePath() + ".");
		long onlyInSecond = outputEachDataTypeOnlyInFirst(dtm2, dtm1);
		output(onlyInSecond + " data types that were only in second archive.");

		output("\nThe following are different kinds of data types.");
		long differentKinds = outputWhereTypesDiffer(dtm1, dtm2);
		output(differentKinds + " data types had different types.");

		output("\nThe following data types are defined differently.");
		long differentDefinitions = outputWhereDefinitionsDiffer(dtm1, dtm2);
		output(differentDefinitions + " data types had different definitions.");

		output("\nThe following data types are different sizes");
		long differentSizes = outputWhereSizesDiffer(dtm1, dtm2);
		output(differentSizes + " data types had different sizes.");

		output("\n");
	}

	private long outputEachDataTypeOnlyInFirst(DataTypeManager dtmArchive1,
			DataTypeManager dtmArchive2) {

		long missingCount = 0;
		Iterator<DataType> allDataTypes = dtmArchive1.getAllDataTypes();
		while (allDataTypes.hasNext()) {
			DataType dataType = allDataTypes.next();
			if (outputIfMissingDataType(dataType, dtmArchive2)) {
				missingCount++;
			}
		}
		return missingCount;
	}

	private bool outputIfMissingDataType(DataType dataType, DataTypeManager dtmArchive) {

		if (!checkPointers && dataType is Pointer) {
			return false;
		}

		if (!checkArrays && dataType is Array) {
			return false;
		}

		DataType matchingDataType = getMatchingDataType(dataType, dtmArchive);
		if (matchingDataType == null) {
			string pathName = dataType.getPathName();
			output(pathName);
			return true;
		}
		return false;
	}

	private DataType getMatchingDataType(DataType dataType, DataTypeManager dtmArchive) {

		if (!matchByName) {
			UniversalID universalID = dataType.getUniversalID();
			if (universalID != null) {
				return dtmArchive.findDataTypeForID(universalID);
			}
		}

		// find by exact path
		DataType fdt = dtmArchive.getDataType(dataType.getCategoryPath(), dataType.getName());
		if (fdt != null) {
			return fdt;
		}

		// find by name
		List<DataType> list = new List<DataType>();
		dtmArchive.findDataTypes(dataType.getName(), list);
		foreach (DataType dtc in list) {
			if (dataType.getCategoryPath()
					.getPath()
					.toLowerCase()
					.equals(dtc.getCategoryPath().getPath().toLowerCase())) {
				return dtc;
			}
		}
		return null;
	}

	private long outputWhereTypesDiffer(DataTypeManager dtmArchive1,
			DataTypeManager dtmArchive2) {

		long differCount = 0;
		Iterator<DataType> allDataTypes = dtmArchive1.getAllDataTypes();
		while (allDataTypes.hasNext()) {
			DataType dataType = allDataTypes.next();
			if (outputIfDifferentTypes(dataType, dtmArchive2)) {
				differCount++;
			}
		}
		return differCount;
	}

	private long outputWhereSizesDiffer(DataTypeManager dtmArchive1,
			DataTypeManager dtmArchive2) {

		long differCount = 0;
		Iterator<DataType> allDataTypes = dtmArchive1.getAllDataTypes();
		while (allDataTypes.hasNext()) {
			DataType dataType = allDataTypes.next();
			if (outputIfDifferentSizes(dataType, dtmArchive2)) {
				differCount++;
			}
		}
		return differCount;
	}

	private bool outputIfDifferentTypes(DataType dataType, DataTypeManager dtmArchive) {

		if (!checkPointers && dataType is Pointer) {
			return false;
		}

		if (!checkArrays && dataType is Array) {
			return false;
		}

		DataType matchingDataType = getMatchingDataType(dataType, dtmArchive);
		if (matchingDataType != null) {
			Class<object> dtClass = dataType.GetType();
			Class<object> sameNamedDtClass = matchingDataType.GetType();
			if (dtClass != sameNamedDtClass) {
				string message = dataType.getPathName() + "   (" + dtClass.getSimpleName() + ") " +
					"   vs   (" + sameNamedDtClass.GetType() + ")";
				output(message);
				return true;
			}
		}
		return false;
	}

	private long outputWhereDefinitionsDiffer(DataTypeManager dtmArchive1,
			DataTypeManager dtmArchive2) {

		long differCount = 0;
		Iterator<DataType> allDataTypes = dtmArchive1.getAllDataTypes();
		while (allDataTypes.hasNext()) {
			DataType dataType = allDataTypes.next();
			if (outputIfDifferentDefinitions(dataType, dtmArchive2)) {
				differCount++;
			}
		}
		return differCount;
	}

	private bool outputIfDifferentDefinitions(DataType dataType,
			DataTypeManager dtmArchive) {

		if (!checkPointers && dataType is Pointer) {
			return false;
		}

		if (!checkArrays && dataType is Array) {
			return false;
		}

		DataType matchingDataType = getMatchingDataType(dataType, dtmArchive);
		if (matchingDataType != null) {
			Class<object> dtClass = dataType.GetType();
			Class<object> sameNamedDtClass = matchingDataType.GetType();
			if (dtClass == sameNamedDtClass) {
				if (dataType is Enum && (((Enum) dataType).getCount() == 1)) {
					// don't check single entry enums.  Size will vary, and they are extracted defines
					return checkEnum((Enum) dataType, (Enum) matchingDataType);
				}
				if (!dataType.isEquivalent(matchingDataType)) {
					string message =
						dataType.getPathName() + "   (" + dtClass.getSimpleName() + ")";
					output(message);
					return true;
				}
			}
		}
		return false;
	}

	private bool checkEnum(Enum e1, Enum e2) {
		if (e1.getCount() != e2.getCount()) {
			return true;
		}
		// Check that the name is the same
		if (!e1.getNames()[0].equals(e2.getNames()[0])) {
			return true;
		}
		// Check the value is the same
		if (e1.getValues()[0] != e2.getValues()[0]) {
			return true;
		}

		return false;
	}

	private bool outputIfDifferentSizes(DataType dataType, DataTypeManager dtmArchive) {

		if (!checkPointers && dataType is Pointer) {
			return false;
		}

		if (!checkArrays && dataType is Array) {
			return false;
		}

		DataType matchingDataType = getMatchingDataType(dataType, dtmArchive);
		if (matchingDataType != null) {
			Class<object> dtClass = dataType.GetType();
			Class<object> sameNamedDtClass = matchingDataType.GetType();
			if (dtClass == sameNamedDtClass) {
				if (dataType is Enum && (((Enum) dataType).getCount() == 1)) {
					// don't check single entry enums.  Size will vary, and they are extracted defines
					return checkEnum((Enum) dataType, (Enum) matchingDataType);
				}
				if (dataType.getLength() != matchingDataType.getLength()) {
					string message = dataType.getPathName() + "   (" + dtClass.getSimpleName() +
						") " + dataType.getLength() + " !=  " + matchingDataType.getLength();
					output(message);
					return true;
				}
			}
		}
		return false;
	}
}
